  "audio_descriptions": [
    {
      "start_time_mmss": "00:00.000",
      "end_time_mmss": "00:07.893",
      "description_text": "La famiglia osserva il calesse sparire in lontananza lungo la strada sterrata."
    },
    {
      "start_time_mmss": "00:23.389",
      "end_time_mmss": "00:33.509",
      "description_text": "Ernest e Anna rientrano in casa seguiti dai bambini. Flo corre verso le scale."
    },
    {
      "start_time_mmss": "00:40.416",
      "end_time_mmss": "00:50.668",
      "description_text": "Il medico si siede alla scrivania e rilegge la lettera. La moglie gli poggia le mani sulle spalle."
    },
    {
      "start_time_mmss": "00:50.668",
      "end_time_mmss": "01:00.921",
      "description_text": "L'uomo sospira profondamente, poi si alza e guarda fuori dalla finestra con espressione pensierosa."
    },
    {
      "start_time_mmss": "01:00.921",
      "end_time_mmss": "01:11.174",
      "description_text": "Franz e la sorellina giocano in giardino, rincorrendosi allegramente attorno al grande albero."
    },
    {
      "start_time_mmss": "01:25.050",
      "end_time_mmss": "01:34.495",
      "description_text": "Jack osserva curioso un uccellino saltellare sull'erba verde, poi sorride molto divertito."
    },
    {
      "start_time_mmss": "01:37.436",
      "end_time_mmss": "01:40.688",
      "description_text": "Anna richiama i figli dal portico."
    },
    {
      "start_time_mmss": "01:48.911",
      "end_time_mmss": "01:55.623",
      "description_text": "I tre fratelli corrono velocemente verso casa, ridendo spensierati."
    },
    {
      "start_time_mmss": "02:06.309",
      "end_time_mmss": "02:18.271",
      "description_text": "All'interno, Marie sta preparando i bagagli. Piega con cura alcuni abiti e li ripone in un baule aperto."
    },
    {
      "start_time_mmss": "02:18.271",
      "end_time_mmss": "02:30.233",
      "description_text": "La governante chiude il coperchio, poi si asciuga una lacrima dal viso con il fazzoletto bianco."
    },
    {
      "start_time_mmss": "02:35.267",
      "end_time_mmss": "02:39.278",
      "description_text": "La casa sembra ormai mezza vuota e silenziosa."
    }
